import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem110 preserva dados operacionais',()=>{for(const [n,titulo,expected] of [["6666191918","Computador Completo Top Intel Core i7 4770, 16GB RAM, SSD 512GB, Bivolt, Preto, Windows 10 Pro, Monitor 23\" Full HD - BluePC CD2E-0135TO","BluePC CD2E-0135TO — Core i7-4770, 16 GB e SSD de 512 GB"],["6778555692","SSD Interno PRODRIVE 240GB 2.5\" SATA III PROSATA301/240G","SSD Prodrive PROSATA301/240G — 240 GB, SATA III de 2,5″"],["6785015658","Perfume Arabe Vulcan Feu EDP 100ML Unisex com NF","Vulcan Feu Eau de Parfum — 100 mL anunciados"]]){const p={id:'mlMLB'+n,titulo,link:'https://produto.mercadolivre.com.br/MLB-'+n,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
